1	"use client";
2	
3	import { useRouter } from "next/navigation";
4	import { useEffect, useRef, useState, useSyncExternalStore } from "react";
5	import { ArrowUp, Paperclip, Mic, X, Gift, Sparkles } from "lucide-react";
6	import { motion, useReducedMotion } from "framer-motion";
7	import { PENDING_PROMPT_KEY, PENDING_PROMPT_IMAGE_KEY } from "@/lib/pending-prompt";
8	import { SIGNUP_GRANT } from "@/lib/credits";
9	
10	// The rotating gradient inside each glow clip MUST be a square that is
11	// larger than the clip's diagonal, or it stops covering the clip partway
12	// through its own rotation and the ring visibly vanishes and returns on a
13	// loop. (The previous `inset-[-50%]` made it 2x the clip in BOTH axes —
14	// e.g. 1372x296 for this wide composer. Rotated 90deg that occupies
15	// 296x1372: only 296px wide, far short of the ~686px the clip needs
16	// covered. Hence "the glow keeps disappearing.")
17	//
18	// 200% width + aspectRatio 1 gives a square of side 2*clipWidth, which
19	// always exceeds the diagonal. Centering uses margins rather than a
20	// translate because `transform` is owned by the rotation keyframes and a
21	// transform in the animation would override any translate set here —
22	// percentage margins (all sides, per spec) resolve against the containing
23	// block's WIDTH, so -100% on both axes lands the square's center exactly
24	// on the clip's center.
25	const SPIN_SQUARE: React.CSSProperties = {
26	  position: "absolute",
27	  left: "50%",
28	  top: "50%",
29	  width: "200%",
30	  aspectRatio: "1",
31	  marginLeft: "-100%",
32	  marginTop: "-100%",
33	};
34	
35	const SUGGESTIONS = [
36	  "A portfolio site for a freelance photographer",
37	  "A landing page for my SaaS product",
38	  "A website for a neighborhood coffee shop",
39	  "A booking page for my consulting practice",
40	];
41	
42	// Downscale + re-encode client-side so a phone photo doesn't blow past
43	// sessionStorage's per-origin quota (or the tokens it costs Claude to look
44	// at it) — a reference image only needs to be legible, not full-resolution.
45	async function downscaleImage(file: File, maxDim = 1400, quality = 0.82): Promise<string> {
46	  const bitmap = await createImageBitmap(file);
47	  const scale = Math.min(1, maxDim / Math.max(bitmap.width, bitmap.height));
48	  const w = Math.round(bitmap.width * scale);
49	  const h = Math.round(bitmap.height * scale);
50	  const canvas = document.createElement("canvas");
51	  canvas.width = w;
52	  canvas.height = h;
53	  const ctx = canvas.getContext("2d");
54	  if (!ctx) throw new Error("canvas unsupported");
55	  ctx.drawImage(bitmap, 0, 0, w, h);
56	  return canvas.toDataURL("image/jpeg", quality);
57	}
58	
59	// The Web Speech API has no types in TypeScript's DOM lib, so this is a
60	// minimal hand-written shim covering exactly the surface used below —
61	// narrower than the real spec on purpose, so it can't quietly drift into
62	// asserting support for members this component never touches.
63	type SpeechRecognitionAlternativeLike = { readonly transcript: string };
64	type SpeechRecognitionResultLike = {
65	  readonly length: number;
66	  readonly [index: number]: SpeechRecognitionAlternativeLike;
67	};
68	type SpeechRecognitionEventLike = {
69	  readonly results: {
70	    readonly length: number;
71	    readonly [index: number]: SpeechRecognitionResultLike;
72	  };
73	};
74	type SpeechRecognitionLike = {
75	  continuous: boolean;
76	  interimResults: boolean;
77	  lang: string;
78	  start: () => void;
79	  stop: () => void;
80	  onresult: ((e: SpeechRecognitionEventLike) => void) | null;
81	  onend: (() => void) | null;
82	  onerror: (() => void) | null;
83	};
84	type SpeechRecognitionCtor = new () => SpeechRecognitionLike;
85	
86	// Narrowed locally rather than via `declare global`: augmenting Window would
87	// collide with the (differently-shaped) definitions any future TS DOM lib
88	// ships for this API.
89	type SpeechCapableWindow = {
90	  SpeechRecognition?: SpeechRecognitionCtor;
91	  webkitSpeechRecognition?: SpeechRecognitionCtor;
92	};
93	
94	function getSpeechRecognition(): SpeechRecognitionCtor | null {
95	  if (typeof window === "undefined") return null;
96	  const w = window as unknown as SpeechCapableWindow;
97	  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
98	}
99	
100	// Feature detection is *external* state: it is unknowable while rendering on
101	// the server, and rendering the mic button in the server HTML would be a
102	// hydration mismatch. useSyncExternalStore is the sanctioned way to express
103	// that — getServerSnapshot() feeds both SSR and the hydration render, and
104	// React re-reads getSnapshot() only once hydration has finished. Support
105	// never changes within a page's life, so subscribe is a no-op.
