1	"use client";
2	
3	import { useSyncExternalStore } from "react";
4	import { PENDING_PROMPT_KEY } from "@/lib/pending-prompt";
5	
6	// sessionStorage is external state that the server cannot see, so the
7	// "picking up where you left off" panel MUST NOT be in the server HTML —
8	// rendering it there would be a hydration mismatch. That is why the old code
9	// read it from an effect; useSyncExternalStore expresses the same guarantee
10	// without the post-paint cascading render the lint rule flags:
11	//
12	//   * getServerSnapshot() (null) is what React uses for the SSR pass AND for
13	//     the hydration render, so server and first client render agree.
14	//   * getSnapshot() is only consulted once hydration has committed.
15	//
16	// The value is a string (or null), so React's Object.is comparison is stable
17	// and this can't loop.
18	const NEVER_CHANGES = () => () => {};
19	
20	function readPendingPrompt() {
21	  try {
22	    return sessionStorage.getItem(PENDING_PROMPT_KEY);
23	  } catch {
24	    // Private-mode / blocked storage — same swallow as the original code.
25	    return null;
26	  }
27	}
28	
29	const noPendingPromptOnServer = () => null;
30	
31	/** The prompt typed on the home page before signing in, if there is one. */
32	export function usePendingPrompt() {
33	  return useSyncExternalStore<string | null>(
34	    NEVER_CHANGES,
35	    readPendingPrompt,
36	    noPendingPromptOnServer,
37	  );
38	}
