              const active = pathname === link.href;
              return (
                <Link
                  key={link.href}
                  href={link.href}
                  // The active link was signalled by colour and a gradient
                  // underline only — nothing a screen reader could hear.
                  aria-current={active ? "page" : undefined}
                  className={`relative py-1 transition-colors ${
                    active
                      ? "text-neutral-900 dark:text-white"
                      : "text-neutral-600 hover:text-neutral-900 dark:text-neutral-400 dark:hover:text-white"
                  }`}
                >
                  {link.label}
                  {active && (
                    <span
                      aria-hidden
                      className="absolute -bottom-1 left-0 right-0 h-px"
                      style={{ background: "var(--brand-gradient)" }}
                    />
                  )}
                </Link>
              );
            })}
            <ThemeToggle />
            <ShineButton>
              <Link
                href="/signup"
                className="inline-block rounded-lg bg-neutral-900 px-4 py-2 text-sm font-medium text-white dark:bg-white dark:text-neutral-900"
              >
                Get started
              </Link>
            </ShineButton>
          </nav>

          <div className="flex items-center gap-2 sm:hidden">
            <ThemeToggle />
            <button
              ref={toggleRef}
              type="button"
              onClick={() => setOpen((v) => !v)}
              className="rounded-md p-2 text-neutral-700 dark:text-neutral-300"
              // Open/closed was conveyed only by swapping the icon glyph.
              // aria-expanded + aria-controls state it properly, and the
              // label now says what pressing it will do.
              aria-label={open ? "Close menu" : "Open menu"}
              aria-expanded={open}
              aria-controls="mobile-nav"
            >
              {open ? <X size={20} /> : <Menu size={20} />}
            </button>
          </div>
        </div>

        <AnimatePresence>
          {open && (
            <motion.nav
              id="mobile-nav"
              aria-label="Main"
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: "auto", opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              transition={{ duration: 0.25, ease: [0.16, 1, 0.3, 1] }}
              className="overflow-hidden sm:hidden"
            >
              <div className="mt-2 flex flex-col gap-1 border-t border-neutral-200/70 px-2 pt-3 text-sm dark:border-neutral-800/70">
                {LINKS.map((link) => (
                  <Link
                    key={link.href}
                    href={link.href}
                    onClick={() => setOpen(false)}
                    aria-current={pathname === link.href ? "page" : undefined}
                    className="rounded-md px-2 py-2.5 text-neutral-700 hover:bg-neutral-100 dark:text-neutral-300 dark:hover:bg-neutral-900"
                  >
                    {link.label}
                  </Link>
                ))}
                <Link
                  href="/signup"
                  onClick={() => setOpen(false)}
                  className="mt-2 rounded-lg bg-neutral-900 px-4 py-2.5 text-center text-sm font-medium text-white dark:bg-white dark:text-neutral-900"
                >
                  Get started
                </Link>
              </div>
            </motion.nav>
          )}
        </AnimatePresence>
      </div>
    </header>
  );
}

"use client";

import { useMemo, useState } from "react";
import Link from "next/link";
import { Search, ArrowRight } from "lucide-react";
import { RevealGroup, RevealItem } from "./Reveal";
import { MotionLift } from "./FloatCard";

type Post = { slug: string; title: string; metaDescription: string; category: string };

export function BlogSearch({ posts }: { posts: Post[] }) {
  const [q, setQ] = useState("");

  const filtered = useMemo(() => {
    const query = q.trim().toLowerCase();
    if (!query) return posts;
    return posts.filter(
      (p) =>
        p.title.toLowerCase().includes(query) ||
        p.metaDescription.toLowerCase().includes(query) ||
        p.category.toLowerCase().includes(query),
    );
  }, [posts, q]);

  const byCategory = useMemo(() => {
    const map = new Map<string, Post[]>();
    for (const post of filtered) {
      const list = map.get(post.category) ?? [];
      list.push(post);
      map.set(post.category, list);
    }
    return map;
  }, [filtered]);

  return (
    <>
      <div className="relative mx-auto mb-14 max-w-md">
        <Search size={16} className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-neutral-400" />
        <input
          type="text"
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder="Search articles…"
          className="w-full rounded-full border border-neutral-200 bg-white/70 py-2.5 pl-11 pr-4 text-sm outline-none backdrop-blur-md transition-colors placeholder:text-neutral-400 focus:border-neutral-400 dark:border-neutral-800 dark:bg-neutral-950/70 dark:placeholder:text-neutral-600 dark:focus:border-neutral-600"
        />
      </div>

      {filtered.length === 0 ? (
        <p className="text-center text-sm text-neutral-500 dark:text-neutral-500">
          No articles match “{q}”.
        </p>
      ) : (
        Array.from(byCategory.entries()).map(([category, items]) => (
          <div key={category} className="mb-16">
            <h2 className="mb-5 flex items-center gap-2 text-sm font-medium uppercase tracking-[0.14em] text-neutral-500 dark:text-neutral-400">
              <span className="h-1.5 w-1.5 rounded-full" style={{ background: "var(--brand-gradient)" }} aria-hidden />
              {category}
            </h2>
            <RevealGroup className="grid gap-5 sm:grid-cols-2" stagger={0.06}>
              {items.map((post) => (
                <RevealItem key={post.slug}>
                  <MotionLift lift={4} className="h-full">
                    <Link
                      href={`/blog/${post.slug}`}
                      className="group flex h-full flex-col rounded-2xl border border-neutral-200 p-6 transition-shadow hover:shadow-lg dark:border-neutral-800"
                    >
                      <h3 className="text-lg font-semibold leading-snug tracking-tight">{post.title}</h3>
                      <p className="mt-2 flex-1 text-sm leading-relaxed text-neutral-600 dark:text-neutral-400">
                        {post.metaDescription}
                      </p>
                      <span className="mt-4 inline-flex items-center gap-1.5 text-sm font-medium text-neutral-900 dark:text-white">
                        Read article
                        <ArrowRight size={14} className="transition-transform group-hover:translate-x-1" />
                      </span>
                    </Link>
                  </MotionLift>
                </RevealItem>
              ))}
            </RevealGroup>
          </div>
        ))
      )}
    </>
  );
}

